def translate_legacy_verification(apps, schema_editor):
    Organization = apps.get_model('employers','Organization')
    for old,new in [('unverified','draft'),('pending','submitted'),('verified','approved')]:
        Organization.objects.filter(verification_status=old).update(verification_status=new)
    # Existing publication is retained but awaits a no-fee attestation/review.
    Vacancy=apps.get_model('employers','EmployerVacancy')
    Vacancy.objects.filter(status='published',no_candidate_fees=False).update(trust_hold=True)


